CREATE TABLE IF NOT EXISTS public.task_guides (
  id SERIAL PRIMARY KEY,
  padrao TEXT NOT NULL UNIQUE,
  ordem INT NOT NULL DEFAULT 100,
  rotulo TEXT NOT NULL,
  guia TEXT NOT NULL
);
GRANT SELECT ON public.task_guides TO authenticated;
GRANT UPDATE ON public.task_guides TO authenticated;
GRANT ALL ON public.task_guides TO service_role;
ALTER TABLE public.task_guides ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS task_guides_select_all ON public.task_guides;
CREATE POLICY task_guides_select_all ON public.task_guides FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS task_guides_update_gestor ON public.task_guides;
CREATE POLICY task_guides_update_gestor ON public.task_guides FOR UPDATE TO authenticated
  USING (public.has_role(auth.uid(), 'gestor')) WITH CHECK (public.has_role(auth.uid(), 'gestor'));

DELETE FROM public.task_guides;
