INSERT INTO public.task_guides (padrao, ordem, rotulo, guia) VALUES
  ('briefing 9:30', 1, 'Briefing de abertura da semana', E'Encontro rápido (10–15 min) com o gestor às 9:30 para definir os objetivos da semana.\n\n1. Leve seus números da semana anterior (contatos, cartões, flyers, visitas).\n2. Combine 1 a 3 metas concretas para a semana (ex.: 3 captações agendadas).\n3. Anote o que precisa de ajuda do gestor.\n4. Saia com o dia já planejado.'),
  ('briefing', 2, 'Briefing diário com o gestor', E'Alinhamento rápido de 5–10 min no início do dia.\n\n1. Diga o que fez ontem e o resultado.\n2. Diga o foco de hoje.\n3. Levante qualquer travamento (objeção, dúvida de script, imóvel).\n4. O gestor ajusta a prioridade se necessário.'),
  ('2h de posicionamento', 3, '2 horas de posicionamento na área', E'Presença física na sua área para ser reconhecido como o corretor daquela região.\n\n1. Vá à área definida no horário combinado.\n2. Circule pelas ruas/comércio, converse com moradores e comerciantes.\n3. Entregue cartões e flyers enquanto anda.\n4. Observe placas de venda (concorrência e FSBO) e anote.\n5. Registre no relatório onde esteve e o que colheu.'),
  ('levantamento de área', 4, 'Levantamento de área (1 de 30 dias)', E'Mapeamento progressivo da sua área ao longo de 30 dias. Cada dia você adiciona um trecho.\n\n1. Escolha o quarteirão/rua do dia.\n2. Registre: imóveis à venda, placas, tipo de imóvel, faixa de preço, contatos de porta.\n3. Fotografe pontos de referência.\n4. Salve na sua planilha/base para virar conhecimento de especialista da região.\n5. Ao fim dos 30 dias você domina a área melhor que qualquer concorrente.'),
  ('entregar 10 cartões do líder', 5, 'Entregar 10 cartões do líder', E'Nos primeiros dias você entrega o cartão do seu líder/gestor enquanto ainda monta o seu.\n\n1. Aborde de forma simpática: apresente-se e diga que faz parte da equipe RE/MAX da região.\n2. Entregue o cartão em mãos (não deixe em caixa de correio).\n3. Diga uma frase de valor: ''se pensar em vender ou comprar, estamos aqui na região''.\n4. Anote quem recebeu bem para retornar depois.'),
  ('entregar 10 cartões', 6, 'Entregar 10 cartões em mãos', E'Meta diária de 10 cartões entregues pessoalmente na sua área.\n\n1. Priorize comércio e moradores da sua área de posicionamento.\n2. Entregue em mãos, com contato visual e uma frase curta de apresentação.\n3. Não empurre: crie familiaridade. O objetivo é ser lembrado.\n4. Registre no relatório.'),
  ('entregar 25 flyers', 7, 'Entregar 25 flyers a residentes', E'Distribuição de material a moradores para adensar sua presença na área.\n\n1. Leve 25 flyers/cartas de apresentação.\n2. Entregue preferencialmente em mãos; onde não houver ninguém, deixe na porta/caixa.\n3. Foque na sua área de posicionamento (repetição na mesma região gera reconhecimento).\n4. Combine com a entrega de cartões para render mais.'),
  ('2h de seguimento à base', 8, '2h de seguimento à base de dados', E'Bloco de tempo para ''aquecer'' os contatos que você já tem.\n\n1. Abra sua base (CIPs, proprietários, FSBOs).\n2. Priorize quem teve interação recente ou está há muito sem contato.\n3. Ligue/mensagem com um motivo real (novidade, imóvel, aniversário, material RE/MAX).\n4. Registre o retorno e agende o próximo toque.\n5. Consistência aqui é o que gera negócio no médio prazo.'),
  ('verificar alertas de portais', 9, 'Verificar alertas de portais (FSBO)', E'FSBO = proprietários vendendo por conta própria (sem imobiliária). São captações em potencial.\n\n1. Abra os portais/sites que você configurou (Zap, OLX, Chaves na Mão etc.).\n2. Filtre anúncios de particulares na sua área.\n3. Anote os novos e entre em contato usando seu script de proprietário.\n4. Registre na base para seguimento.'),
  ('enviar 10 sms a cips', 10, 'Enviar 10 SMS a CIPs', E'CIPs = contatos conhecidos (amigos, parentes, ex-colegas). Rede quente.\n\n1. Selecione 10 CIPs que ainda não sabem do seu novo projeto.\n2. Mande uma mensagem pessoal e curta (não copie-e-cole genérico).\n3. Conte que agora é corretor RE/MAX e peça indicações.\n4. Anote respostas e insira/atualize na base.'),
  ('cips por messenger', 11, 'Contactar 10 CIPs por messenger', E'Divulgar seu novo projeto para a rede quente pelo Messenger/WhatsApp.\n\n1. Escolha 10 CIPs.\n2. Mensagem pessoal: cumprimente, conte que virou corretor RE/MAX na região.\n3. Peça para compartilharem/indicarem quem pensa em vender ou comprar.\n4. Registre na base.'),
  ('cips na base', 12, 'Contactar 10 CIPs e inserir na base', E'Trabalhar contatos conhecidos e cadastrá-los para seguimento futuro.\n\n1. Contate 10 CIPs (ligação ou mensagem).\n2. Apresente seu projeto e pergunte se conhecem alguém querendo vender/comprar.\n3. Cadastre cada um na sua base de dados com nome, contato e observação.\n4. Marque o próximo toque.'),
  ('cips no maxwork', 13, 'Contactar 10 CIPs no maxwork', E'Mesmo trabalho de CIPs, registrando no sistema maxwork da RE/MAX.\n\n1. Contate 10 conhecidos.\n2. Apresente seu projeto e peça indicações.\n3. Registre cada contato no maxwork para não perder o histórico.'),
  ('cips (conhecidos) e inserir no excel', 14, 'Contactar 10 CIPs e inserir no Excel', E'Primeiros contatos da rede quente, cadastrados na sua planilha.\n\n1. Liste 10 conhecidos.\n2. Ligue/mensagem apresentando seu novo trabalho.\n3. Cadastre no Excel: nome, telefone, relação, observação.\n4. Marque quem demonstrou interesse.'),
  ('10 potenciais e inserir no excel', 15, 'Contactar 10 potenciais', E'Primeiro exercício de prospecção: 10 contatos com potencial.\n\n1. Use seu script de contato.\n2. Foque em quem pode comprar, vender ou indicar.\n3. Cadastre no Excel com o resultado da conversa.\n4. Agende retorno para os promissores.'),
  ('enviar relatório diário', 16, 'Enviar relatório diário', E'Fechamento do dia — no app isto é automático ao concluir o dia.\n\n1. Marque as tarefas concluídas ao longo do dia.\n2. Escreva no campo de notas suas maiores dificuldades.\n3. Toque em ''Enviar relatório do dia''.\n4. O gestor recebe seu progresso em tempo real e consegue te ajudar cedo.'),
  ('saída de rua', 17, 'Saída de rua com a equipe', E'Ação de rua em grupo (4ª ou 5ª feira) para captar e divulgar em bloco.\n\n1. Confirme ponto e horário com a equipe.\n2. Leve cartões, flyers e material de captação.\n3. Trabalhem a área juntos — dá segurança e cobre mais terreno.\n4. Registre contatos e captações no fim.'),
  ('saída de equipe', 18, 'Saída de equipe (ação de rua)', E'Atividade coletiva de rua para adensar presença e captar.\n\n1. Alinhe área e metas com a equipe.\n2. Distribua material e aborde moradores/comércio.\n3. Some os contatos ao fim e registre na base.'),
  ('inserir post nas redes (2ªf)', 19, 'Post nas redes (segunda-feira)', E'Abertura de semana nas redes com conteúdo leve (clima, frase, dia comemorativo).\n\n1. Poste algo generalista de bom gosto (não venda direta).\n2. Objetivo: manter presença e humanizar seu perfil.\n3. Use a identidade RE/MAX.\n4. Responda comentários/DMs.'),
  ('inserir post nas redes', 20, 'Inserir post nas redes', E'Manter o perfil ativo com conteúdo relevante.\n\n1. Publique algo útil ou de relacionamento (dica, bastidor, imóvel, data comemorativa).\n2. Mantenha frequência.\n3. Interaja com quem comentar.'),
  ('post no facebook divulgando', 21, 'Post divulgando o novo projeto', E'Anúncio público de que você agora é corretor RE/MAX.\n\n1. Escreva um post pessoal contando a novidade e o porquê.\n2. Marque a RE/MAX Única Escolha.\n3. Chame para contato quem pensa em vender/comprar.\n4. Fixe no perfil.'),
  ('post no facebook', 22, 'Post no Facebook', E'Publicação para manter presença e gerar contato.\n\n1. Poste conteúdo relevante da semana (imóvel, dica, novidade).\n2. Inclua chamada para ação (comente/DM).\n3. Responda interações.'),
  ('post à procura de captações', 23, 'Post à procura de captações', E'Conteúdo pedindo imóveis para vender.\n\n1. Poste algo do tipo ''tenho compradores procurando na região X''.\n2. Peça para marcarem quem quer vender.\n3. Direcione para o seu contato.'),
  ('preparar posts de dias comemorativos', 24, 'Preparar posts de datas comemorativas', E'Planejar com antecedência os posts das datas da semana.\n\n1. Liste as datas comemorativas da semana.\n2. Crie/agende os posts com identidade RE/MAX.\n3. Deixe pronto para publicar no dia certo.'),
  ('levantar dias comemorativos', 25, 'Levantar datas comemorativas e preparar posts', E'Antecipar o calendário para não perder oportunidades de conteúdo.\n\n1. Consulte as datas do mês/semana.\n2. Escolha as relevantes para o seu público.\n3. Prepare os posts com antecedência.'),
  ('prospecção telefônica', 26, 'Prospecção telefônica a proprietários', E'Ligar para proprietários (geralmente FSBO da internet) com seu script.\n\n1. Tenha a lista e o script à mão.\n2. Ligue com objetivo de agendar uma visita/avaliação, não de vender no telefone.\n3. Contorne objeções com calma (use a reciclagem de objeções).\n4. Registre cada ligação e o próximo passo.'),
  ('levantar 10 proprietários', 27, 'Levantar 10 proprietários na internet', E'Garimpar anúncios de particulares para prospectar.\n\n1. Vasculhe portais filtrando anúncios de proprietário.\n2. Colete contato, endereço e características.\n3. Cadastre na base para ligar depois.'),
  ('levantar imóveis à venda e vendidos', 28, 'Levantar imóveis à venda e vendidos', E'Conhecer o estoque e o histórico da sua área.\n\n1. Liste no site RE/MAX e nos portais o que está à venda e o que já vendeu na área.\n2. Anote preços e tempo de anúncio — isso alimenta seu estudo de mercado.\n3. Guarde para argumentar valor com proprietários.'),
  ('levantar imóveis fora da rede', 29, 'Levantar imóveis fora da rede RE/MAX', E'Mapear a concorrência para parcerias e conhecimento de mercado.\n\n1. Liste imóveis de outras imobiliárias/particulares na sua área.\n2. Anote condições que possam virar parceria.\n3. Registre preços para comparação.'),
  ('continuar levantamento de imóveis da concorrência', 30, 'Levantamento de imóveis da concorrência', E'Dar sequência ao mapeamento da concorrência.\n\n1. Atualize sua lista de imóveis de concorrentes na área.\n2. Observe reajustes de preço e imóveis parados.\n3. Use para abordar proprietários insatisfeitos.'),
  ('levantar placas da concorrência', 31, 'Levantar placas da concorrência', E'Placas indicam proprietários que já querem vender.\n\n1. Percorra a área anotando placas de outras imobiliárias e de particulares.\n2. Registre endereço e telefone quando houver.\n3. FSBOs viram alvo de captação; concorrência parada vira oportunidade.'),
  ('acompanhar colega numa aps', 32, 'Acompanhar colega numa APS', E'APS = Apresentação de Estudo de Mercado ao proprietário. Aprenda observando.\n\n1. Combine com o colega para assistir.\n2. Observe como ele apresenta o preço e contorna objeções.\n3. Anote frases e a estrutura para replicar.\n4. Depois, comente com ele o que aprendeu.'),
  ('acompanhar colega em visita com compradores', 33, 'Acompanhar visita com compradores', E'Aprender a conduzir uma visita observando um colega.\n\n1. Vá junto numa visita com comprador.\n2. Observe a recepção, o roteiro do imóvel e o fechamento.\n3. Anote como ele lê sinais de interesse.\n4. Pratique depois.'),
  ('acompanhar colega numa visita', 34, 'Acompanhar colega numa visita', E'Vivência prática ao lado de alguém mais experiente.\n\n1. Combine para acompanhar.\n2. Observe postura, escuta e condução.\n3. Anote o que funcionou.\n4. Traga dúvidas ao gestor.'),
  ('acompanhar colega numa captação', 35, 'Acompanhar colega numa captação', E'Ver na prática como se capta um imóvel em exclusivo.\n\n1. Vá junto à visita de captação.\n2. Observe a apresentação do serviço e do plano de marketing.\n3. Note como o colega defende a exclusividade e o preço.\n4. Replique com seu estilo.'),
  ('acompanhar colega na escala', 36, 'Acompanhar colega na escala', E'Escala = plantão de atendimento a quem chega à agência.\n\n1. Fique com um colega durante o plantão.\n2. Observe como ele qualifica quem chega.\n3. Aprenda a transformar atendimento em oportunidade.'),
  ('reciclagem de objeções', 37, 'Reciclagem de objeções para captação', E'Treino das respostas às objeções mais comuns de proprietários.\n\n1. Revise as objeções típicas (''quero tentar sozinho'', ''comissão é alta'', ''já tenho outra imobiliária'').\n2. Pratique a resposta em voz alta ou em dupla.\n3. Foque em valor e serviço, não em preço.\n4. Leve para a próxima ligação/visita.'),
  ('reciclagem / teatros', 38, 'Reciclagem / teatros de venda', E'Simulação de situações reais de venda em grupo.\n\n1. Participe do role-play com a equipe.\n2. Assuma o papel de corretor e de cliente.\n3. Receba e dê feedback.\n4. Ajuste seu script com o que aprender.'),
  ('teatros de venda', 39, 'Teatros de venda (treino)', E'Encenação de atendimentos para treinar abordagem e fechamento.\n\n1. Participe ativamente, não só assistindo.\n2. Pratique abertura, contorno de objeção e fechamento.\n3. Anote o que travou para melhorar.'),
  ('formação (3ªf)', 40, 'Formação / treino na agência', E'Capacitação semanal da equipe (terça-feira).\n\n1. Chegue no horário com material para anotar.\n2. Participe e tire dúvidas.\n3. Aplique o conteúdo já na semana.'),
  ('reunião de equipe', 41, 'Reunião de equipe', E'Encontro (6ª feira, quinzenal) de alinhamento e resultados.\n\n1. Leve seus números e casos da quinzena.\n2. Compartilhe dificuldades e vitórias.\n3. Saia com metas claras.'),
  ('criar página no facebook', 42, 'Criar perfis nas redes sociais', E'Montar sua presença profissional online.\n\n1. Crie/ajuste perfis no Facebook, Instagram e LinkedIn como corretor RE/MAX.\n2. Use foto profissional, bio clara e contato.\n3. Padronize com a identidade RE/MAX.\n4. Faça o primeiro post de apresentação.'),
  ('montar dossier', 43, 'Montar dossier de apresentação', E'Material que você mostra ao proprietário para vender seu serviço.\n\n1. Reúna: quem é a RE/MAX, seu plano de marketing, estudo de mercado modelo e cases.\n2. Deixe visualmente limpo e profissional.\n3. Tenha versão digital e impressa.\n4. Use nas visitas de captação.'),
  ('levantar imobiliárias da área', 44, 'Levantar imobiliárias da área', E'Conhecer quem atua na sua região.\n\n1. Liste as imobiliárias e corretores ativos na área.\n2. Anote pontos fortes e fracos de cada uma.\n3. Isso ajuda a posicionar seu diferencial e a fazer parcerias.'),
  ('criar scripts de prospecção', 45, 'Criar scripts de prospecção', E'Ter um roteiro pronto evita travar na hora do contato.\n\n1. Escreva aberturas para proprietário, comprador e indicação.\n2. Inclua respostas às objeções mais comuns.\n3. Teste e ajuste com o uso.\n4. Peça revisão ao gestor.'),
  ('criar scripts de contatos', 46, 'Criar scripts de contatos', E'Roteiros para abordar sua rede de conhecidos (CIPs).\n\n1. Escreva uma mensagem/ligação de apresentação do seu novo projeto.\n2. Faça variações para diferentes graus de proximidade.\n3. Sempre termine pedindo indicação.'),
  ('levantar portais/sites e criar contas', 47, 'Cadastrar-se nos portais', E'Preparar os canais onde você vai anunciar e prospectar.\n\n1. Liste os portais relevantes (Zap, OLX, Chaves na Mão etc.).\n2. Crie suas contas.\n3. Configure alertas de FSBO na sua área.\n4. Deixe pronto para publicar imóveis.'),
  ('explorar as plataformas re/max', 48, 'Explorar as plataformas RE/MAX', E'Conhecer as ferramentas que a rede oferece.\n\n1. Navegue pelos sites nacional e internacional, redes e canais RE/MAX.\n2. Veja como buscar imóveis e compartilhar.\n3. Anote o que pode usar no dia a dia.'),
  ('enviar email aos cips', 49, 'Enviar e-mail aos CIPs', E'Comunicado da sua nova atuação para a rede quente.\n\n1. Escreva um e-mail pessoal e caloroso contando que virou corretor RE/MAX.\n2. Peça indicações.\n3. Envie e registre quem respondeu.'),
  ('iniciar entrega de blocos de notas', 50, 'Entregar blocos de notas no comércio', E'Blocos personalizados ficam no balcão do comércio divulgando você o tempo todo.\n\n1. Comece pelo comércio da sua área.\n2. Ofereça o bloco de brinde com seu contato.\n3. Explique que é útil para o balcão.\n4. Registre onde deixou para repor depois.'),
  ('continuar entrega de blocos', 51, 'Continuar entrega de blocos de notas', E'Dar sequência à distribuição no comércio.\n\n1. Visite novos pontos de comércio da área.\n2. Deixe os blocos e reforce relacionamento.\n3. Reponha onde já acabou.'),
  ('preparar blocos de notas', 52, 'Preparar blocos de notas', E'Deixar o material pronto para distribuir.\n\n1. Confira se os blocos estão com seu contato e identidade RE/MAX.\n2. Organize a quantidade para a semana.\n3. Planeje os pontos de entrega.'),
  ('preparar flyer/carta', 53, 'Preparar flyer/carta de apresentação', E'Material que apresenta você aos moradores.\n\n1. Monte um flyer/carta com foto, contato e diferencial.\n2. Use identidade RE/MAX.\n3. Revise com o gestor antes de imprimir.'),
  ('verificar flyers/cartas', 54, 'Verificar flyers/cartas', E'Conferir se o material está pronto e suficiente.\n\n1. Revise conteúdo e quantidade.\n2. Ajuste erros.\n3. Garanta estoque para a distribuição da semana.'),
  ('preparar revista/flyer de parceria', 55, 'Flyer de parceria com o comércio', E'Material que ''vende'' a ideia de parceria aos comerciantes.\n\n1. Monte um exemplo mostrando como o comércio ganha visibilidade com você.\n2. Use como demonstração — só imprima na gráfica após acordo.\n3. Leve nas visitas ao comércio.'),
  ('criar flyer "atacar placas', 56, 'Flyer para ''atacar placas'' da concorrência', E'Material específico para abordar imóveis com placa de concorrente.\n\n1. Crie um flyer que destaque seu diferencial de serviço.\n2. Direcione a proprietários que já querem vender.\n3. Use com tato — foco em valor, não em crítica ao concorrente.'),
  ('enviar flyers de parceria à gráfica', 57, 'Enviar flyers à gráfica', E'Produção final do material aprovado.\n\n1. Feche a arte com as condições acordadas.\n2. Envie para impressão.\n3. Combine prazo e retirada.'),
  ('preparar distribuição de flyers', 58, 'Preparar distribuição de flyers', E'Planejar a entrega do material que chegou.\n\n1. Separe por área/rota.\n2. Defina os dias de distribuição.\n3. Combine apoio da equipe se precisar.'),
  ('colocar expositor', 59, 'Colocar expositor na área', E'Expositor A4/A5 no comércio trabalha por você 24h.\n\n1. Escolha pontos de bom fluxo na área.\n2. Personalize com seus imóveis/contato.\n3. Combine com o comerciante.\n4. Reponha a publicidade toda 2ª feira e deixe material para o fim de semana na 6ª.'),
  ('deixar publicidade 6ªf no comércio', 60, 'Deixar publicidade na sexta', E'Abastecer o comércio antes do fim de semana movimentado.\n\n1. Reponha flyers/expositores na 6ª feira.\n2. Foque nos pontos de maior fluxo.\n3. Garanta que sua marca fique visível no fim de semana.'),
  ('fechar parceria com café', 61, 'Parceria com café (1 levantamento = 1 café)', E'Ação para captar contatos de moradores em troca de um mimo.\n\n1. Combine com um café da área a oferta de um café por levantamento preenchido.\n2. Tenha o formulário com campos obrigatórios.\n3. Divulgue e recolha os contatos para a base.\n4. Agradeça o parceiro e divulgue-o também.'),
  ('fechar parceria com cabeleireiro', 62, 'Parceria com cabeleireiro (1 flyer = 1 benefício)', E'Gerar benefício aos moradores e visibilidade mútua.\n\n1. Combine um desconto/benefício mediante apresentação do seu flyer.\n2. No flyer, faça publicidade do parceiro também.\n3. Distribua na área.\n4. Acompanhe o resultado.'),
  ('definir plano anual de publicidade', 63, 'Plano anual de publicidade', E'Organizar seus investimentos de divulgação no ano.\n\n1. Liste as datas comemorativas e picos do mercado.\n2. Distribua orçamento por mês/campanha.\n3. Priorize o que gera captação.\n4. Revise trimestralmente.'),
  ('definir dia fixo da newsletter', 64, 'Newsletter mensal (Sendinblue/Mailchimp)', E'Manter contato regular com sua base por e-mail.\n\n1. Defina um dia fixo do mês.\n2. Aprenda o básico do Sendinblue ou Mailchimp.\n3. Monte um modelo com apoio do designer do grupo.\n4. Envie novidades e imóveis para a base.'),
  ('levantar 5 fsbos', 65, 'Levantar 5 FSBOs e contactar', E'FSBO = proprietário vendendo sozinho. São suas melhores captações.\n\n1. Encontre 5 anúncios de particular na área.\n2. Contate com seu script de proprietário.\n3. Objetivo: agendar visita/avaliação.\n4. Registre na base.'),
  ('bloco de tempo para seguimento a fsbos', 66, 'Bloco de tempo para seguimento a FSBOs', E'Reservar horário na agenda só para retornar aos FSBOs.\n\n1. Bloqueie um horário fixo.\n2. Retome contato com os FSBOs já cadastrados.\n3. Avance cada um para o próximo passo (visita, avaliação).\n4. Registre.'),
  ('preparar pesquisa sobre a área', 67, 'Preparar pesquisa sobre a área', E'Consolidar seu conhecimento da região em material útil.\n\n1. Reúna dados do seu levantamento (preços, perfil, tempo de venda).\n2. Organize num resumo apresentável.\n3. Use para se posicionar como especialista da área.'),
  ('agendar próximo evento', 68, 'Agendar próximo evento na área', E'Manter uma agenda de ações de relacionamento.\n\n1. Defina a próxima ação (parceria, café, mutirão).\n2. Combine data e parceiros.\n3. Divulgue com antecedência.'),
  ('assistir ao filme', 69, 'Assistir ao filme (motivacional)', E'Conteúdo de mentalidade para reforçar persistência.\n\n1. Assista ao filme indicado.\n2. Anote 1 aprendizado que se aplica à sua rotina.\n3. Comente com a equipe/gestor.'),
  ('iniciar a área de posicionamento', 70, 'Iniciar a área de posicionamento', E'Escolher e começar a trabalhar a região que será a sua.\n\n1. Defina uma área com potencial e tamanho que você consiga cobrir.\n2. Comece a circular e observar.\n3. É aqui que todo o resto (cartões, flyers, levantamento) vai se concentrar.'),
  ('contactar 10 cips', 900, 'Contactar 10 CIPs', E'Trabalhar contatos conhecidos da sua rede quente.\n\n1. Selecione 10 CIPs.\n2. Apresente seu projeto e peça indicações.\n3. Registre cada um na base para seguimento.'),
  ('_estudo', 9999, 'Estudo / capítulo de capacitação', E'Esta é uma tarefa de estudo ligada ao capítulo do dia.\n\n1. Leia o capítulo indicado do livro ''Caminho para o Sucesso'' (Mônica Silva).\n2. Anote 2–3 ideias que você aplica já esta semana.\n3. Marque como concluída após a leitura.\n4. Leve dúvidas ao briefing.');